  resp = await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
    method: 'GET',
    url: `${SUPABASE_URL}/rest/v1/workflow_proposals?status=eq.executing&select=*`,
    json: true,
    timeout: 10000,
  });
} catch (e) {
  return [{ json: { skip: true, message: `Supabase fetch failed: ${e.message}` } }];
}
const proposals = typeof resp === 'string' ? JSON.parse(resp) : resp;
if (!proposals || proposals.length === 0) {
  return [{ json: { skip: true, message: 'No executing proposals to monitor' } }];
}
