// patched: getCredentials -> httpRequestWithAuthentication
const SUPABASE_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';

const proposal = $input.first().json;
if (proposal.skip) {
  return [{ json: { skip: true, message: proposal.message, alerts: [] } }];
}

const result = {
  proposalId: proposal.id,
  title: proposal.title,
  workflowId: proposal.current_workflow_id,
  rollbackId: proposal.rollback_workflow_id,
  action: 'monitor',
  alerts: [],
};

try {
  if (!proposal.current_workflow_id) {
    result.action = 'skip';
    result.reason = 'No workflow to monitor (new workflow proposal)';
    return [{ json: result }];
  }
  const runsUrl = `${SUPABASE_URL}/rest/v1/workflow_runs?workflow_id=eq.${proposal.current_workflow_id}&order=run_at.desc&limit=20&select=*`;
  const runsResp = await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
    url: runsUrl,
    json: true,
    timeout: 10000,
  });
  const runs = typeof runsResp === 'string' ? JSON.parse(runsResp) : (runsResp || []);
  const successCount = runs.filter(r => r.outcome === 'success' || r.status === 'success').length;
  const totalCount = runs.length;
  const successRate = totalCount > 0 ? (successCount / totalCount) * 100 : null;
  result.successRate = successRate;
  result.runCount = totalCount;

  if (totalCount >= 5 && successRate !== null && successRate < 60) {
    result.action = 'rollback';
    result.reason = `Success rate ${successRate.toFixed(1)}% below 60% threshold over ${totalCount} runs`;
    result.alerts.push(`ROLLBACK: ${proposal.title} - ${result.reason}`);
  } else if (totalCount >= 5 && successRate !== null && successRate >= 95) {
    result.action = 'complete';
    result.reason = `Success rate ${successRate.toFixed(1)}% over ${totalCount} runs - promote to completed`;
  } else {
    result.action = 'monitor';
    result.reason = `Insufficient data or healthy (${totalCount} runs, ${successRate === null ? 'n/a' : successRate.toFixed(1)+'%'} success)`;
  }
} catch (err) {
  result.action = 'error';
  result.reason = `Check failed: ${err.message}`;
  result.alerts.push(`Quality check error for ${proposal.title}: ${err.message}`);
}
return [{ json: result }];

// patched: getCredentials -> httpRequestWithAuthentication
const SUPABASE_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const N8N_URL = 'https://krishraja10101.app.n8n.cloud/api/v1';
const HTTP_TIMEOUT = 10000;

const data = $input.first().json;
if (data.skip || (data.action !== 'rollback' && data.action !== 'complete')) {
  return [{ json: data }];
}

const now = new Date().toISOString();

try {
  if (data.action === 'rollback' && data.rollbackId && data.workflowId) {
    const backup = await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
      method: 'GET',
      url: `${N8N_URL}/workflows/${data.rollbackId}`,
      json: true, timeout: HTTP_TIMEOUT,
    });
    if (backup && backup.nodes) {
      const orig = await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
        method: 'GET',
        url: `${N8N_URL}/workflows/${data.workflowId}`,
        json: true, timeout: HTTP_TIMEOUT,
      });
      const restorePayload = {
        name: (orig && orig.name) || backup.name,
        nodes: backup.nodes,
        connections: backup.connections,
        settings: backup.settings || {},
      };
      await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
        method: 'PUT',
        url: `${N8N_URL}/workflows/${data.workflowId}`,
        headers: { 'Content-Type': 'application/json' },
        body: restorePayload, json: true, timeout: HTTP_TIMEOUT,
      });
      data.rollbackPerformed = true;
      data.rollbackAt = now;
      await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
        method: 'PATCH',
        url: `${SUPABASE_URL}/rest/v1/workflow_proposals?id=eq.${data.proposalId}`,
        headers: { 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
        body: { status: 'rolled_back', updated_at: now, rollback_reason: data.reason },
        json: true, timeout: HTTP_TIMEOUT,
      });
    } else {
      data.rollbackPerformed = false;
      data.rollbackError = 'Backup workflow not found or empty';
    }
  } else if (data.action === 'complete') {
    await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
      method: 'PATCH',
      url: `${SUPABASE_URL}/rest/v1/workflow_proposals?id=eq.${data.proposalId}`,
      headers: { 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
      body: { status: 'completed', updated_at: now, completion_reason: data.reason },
      json: true, timeout: HTTP_TIMEOUT,
    });
    data.markedComplete = true;
  }
} catch (err) {
  data.rollbackError = err.message;
  (data.alerts = data.alerts || []).push(`Auto-Rollback error on ${data.proposalId}: ${err.message}`);
}
return [{ json: data }];

// patched: getCredentials -> httpRequestWithAuthentication
const SUPABASE_URL = 'https://gojpffsrxybbpbdzzrvs.supabase.co';
const N8N_URL = 'https://krishraja10101.app.n8n.cloud/api/v1';
const HTTP_TIMEOUT = 8000;

const prevData = $input.first().json;
const alerts = prevData.alerts || [];
const budgetActions = [];

try {
  const agentsResp = await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
    url: `${SUPABASE_URL}/rest/v1/agent_capabilities?select=*&monthly_budget_usd=gt.0`,
    json: true, timeout: HTTP_TIMEOUT,
  });
  const agents = typeof agentsResp === 'string' ? JSON.parse(agentsResp) : (agentsResp || []);
  if (agents.length === 0) {
    return [{ json: { ...prevData, alerts, budgetActions, budgetMessage: 'No agents with budgets found' } }];
  }
  const monthStart = new Date(new Date().getFullYear(), new Date().getMonth(), 1).toISOString();
  const ids = agents.map(a => a.agent_id).filter(Boolean);
  let runs = [];
  if (ids.length > 0) {
    const inFilter = ids.map(id => `"${id}"`).join(',');
    const runsResp = await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
      url: `${SUPABASE_URL}/rest/v1/workflow_runs?agent_id=in.(${encodeURIComponent(inFilter)})&run_at=gte.${monthStart}&select=agent_id,cost_usd`,
      json: true, timeout: HTTP_TIMEOUT,
    });
    runs = typeof runsResp === 'string' ? JSON.parse(runsResp) : (runsResp || []);
  }
  const costByAgent = {};
  for (const r of runs) {
    const aid = r.agent_id || 'unknown';
    costByAgent[aid] = (costByAgent[aid] || 0) + parseFloat(r.cost_usd || 0);
  }
  for (const agent of agents) {
    const budget = parseFloat(agent.monthly_budget_usd || 0);
    if (!budget) continue;
    const currentSpend = parseFloat(agent.monthly_spend_usd || 0);
    const totalRunCost = costByAgent[agent.agent_id] || 0;
    const totalSpend = Math.max(currentSpend, totalRunCost);
    const usagePercent = (totalSpend / budget) * 100;
    if (usagePercent > 100) {
      alerts.push(`BUDGET KILL: ${agent.agent_id} at ${usagePercent.toFixed(1)}% of $${budget} budget`);
      budgetActions.push({ agent: agent.agent_id, action: 'deactivate', usage: usagePercent });
      if (agent.current_workflow_id) {
        try {
          await this.helpers.httpRequestWithAuthentication.call(this, 'httpHeaderAuth', {
            method: 'POST',
            url: `${N8N_URL}/workflows/${agent.current_workflow_id}/deactivate`,
            json: true, timeout: HTTP_TIMEOUT,
          });
          alerts.push(`Deactivated workflow ${agent.current_workflow_id} for ${agent.agent_id}`);
        } catch (e) {
          alerts.push(`Failed to deactivate ${agent.current_workflow_id}: ${e.message}`);
        }
      }
      try {
        await this.helpers.httpRequestWithAuthentication.call(this, 'supabaseApi', {
          url: `${SUPABASE_URL}/rest/v1/agent_capabilities?agent_id=eq.${agent.agent_id}`,
          method: 'PATCH', json: true,
          headers: { 'Content-Type': 'application/json', 'Prefer': 'return=minimal' },
          body: { active: false, updated_at: new Date().toISOString() },
          timeout: HTTP_TIMEOUT,
        });
      } catch (e) {
        alerts.push(`Failed to flag inactive ${agent.agent_id}: ${e.message}`);
      }
    } else if (usagePercent > 90) {
      alerts.push(`BUDGET WARNING: ${agent.agent_id} at ${usagePercent.toFixed(1)}% of $${budget} budget`);
      budgetActions.push({ agent: agent.agent_id, action: 'warn', usage: usagePercent });
    } else if (usagePercent > 80) {
      alerts.push(`Budget notice: ${agent.agent_id} at ${usagePercent.toFixed(1)}% of $${budget} budget`);
      budgetActions.push({ agent: agent.agent_id, action: 'notice', usage: usagePercent });
    }
  }
} catch (err) {
  alerts.push(`Budget check error: ${err.message}`);
}
return [{ json: { ...prevData, alerts, budgetActions } }];

